import{_ as a,o as e,c as o,a5 as p}from"./chunks/framework.Cooo9kuv.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"IM011-批量统一图片大小指定图片尺寸","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图片尺寸","批量调整图片大小","批量调整图片尺寸","指定图片大小","统一图片尺寸"]},"headers":[],"relativePath":"md/图片批处理/IM011-批量统一图片大小指定图片尺寸.md","filePath":"md/图片批处理/IM011-批量统一图片大小指定图片尺寸.md"}'),n={name:"md/图片批处理/IM011-批量统一图片大小指定图片尺寸.md"};function r(s,t,_,m,g,c){return e(),o("div",null,[...t[0]||(t[0]=[p('<p>批量统一图片尺寸为指定尺寸大小</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224164157174038651730137.png" alt=""></p><p>A文件夹下有B、C、D、F、G....等文件夹，每个文件夹下都有一定的图片，将程序放在A文件夹下，运行程序后，会自动为B、C、D、F、G....等文件夹创建一个副本文件夹，将所有处理统一过尺寸的文件放在副本文件夹内，不影响原来的文件夹内的图片大小。</p><p>该程序适合宽高比差不多，或者微小尺寸调整，如果每张图片相差太多，会造成图片拉伸。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224164452174038669267221.png" alt=""></p><h3 id="imagemagick安装方式" tabindex="-1">ImageMagick安装方式 <a class="header-anchor" href="#imagemagick安装方式" aria-label="Permalink to &quot;ImageMagick安装方式&quot;">​</a></h3><p>先在电脑D盘创建文件夹：ImageMagick  然后将其安装在这个文件夹内</p><p>如果电脑没有D盘则在C盘按照此方式创建文件夹安装</p><p>如果你是win32位操作系统则使用32位的程序（X86）安装，如果是64位操作系统则按照64位的程序（X64）安装</p><p><strong>ImageMagick下载：</strong></p><p>通过网盘分享的文件：ImageMagick安装（必须安装此工具）<br> 链接: <a href="https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti" target="_blank" rel="noreferrer">https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti</a> 提取码: myti</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1499.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1499.html</a></p>',13)])])}const d=a(n,[["render",r]]);export{l as __pageData,d as default};
